  routes.forEach(route => event.modify(route.target, loot => {
    const profile = profiles[route.profile];
    loot.addPool(pool => {
      pool.rolls = 1;
      pool.addCondition({condition: "minecraft:random_chance", chance: profile.chance});
      profile.items.forEach(entry => pool.addItem(Item.of(entry.item, entry.count), entry.weight));
    });
  }));
